application.css:
* { box-sizing: border-box; }

:root {
  color-scheme: light;
  --ink: #182230;
  --muted: #536273;
  --line: #cbd5e1;
  --surface: #ffffff;
  --background: #f3f6fa;
  --accent: #155e75;
  --accent-dark: #0c4a5d;
  --danger: #a32323;
  --success-bg: #e8f6ee;
  --success-ink: #14532d;
}

body {
  margin: 0;
  background: var(--background);
  color: var(--ink);
  font: 1rem/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.page-shell { width: min(100% - 2rem, 920px); margin: 0 auto; padding: 3rem 0; }
.page-header { margin-bottom: 1.75rem; }
.eyebrow { margin: 0 0 .35rem; color: var(--accent); font-size: .8rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
h1, h2 { line-height: 1.2; }
h1 { margin: 0 0 .65rem; font-size: clamp(2rem, 5vw, 3rem); }
h2 { margin: 0 0 1.25rem; font-size: 1.35rem; }
.intro { max-width: 60ch; margin: 0; color: var(--muted); }
.panel { margin-bottom: 1.5rem; padding: clamp(1.25rem, 4vw, 2rem); background: var(--surface); border: 1px solid var(--line); border-radius: .8rem; box-shadow: 0 5px 18px rgba(25,  forty, 60, .05); }
.form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1.1rem; }
.field { display: flex; flex-direction: column; gap: .4rem; }
.field-wide { grid-column: 1 / -1; }
label { font-weight: 650; }
input, select { width: 100%; min-height: 2.75rem; padding: .55rem .7rem; color: var(--ink); background: #fff; border: 1px solid #8997a8; border-radius: .4rem; font: inherit; }
input:focus, select:focus, button:focus-visible { outline: 3px solid #f59e0b; outline-offset: 2px; }
.field-help { margin: 0; color: var(--muted); font-size: .85rem; }
.primary-button, .cancel-button { border: 0; border-radius: .4rem; font: inherit; font-weight: 700; cursor: pointer; }
.primary-button { margin-top: 1.3rem; padding: .7rem 1.15rem; color: white; background: var(--accent); }
.primary-button:hover { background: var(--accent-dark); }
.error-message { margin: 1rem 0 0; color: var(--danger); font-weight: 650; }
.section-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; }
.booking-count { color: var(--muted); font-size: .9rem; }
.confirmation { margin: 0 0 1rem; padding: .75rem 1rem; color: var(--success-ink); background: var(--success-bg); border-radius: .4rem; }
.booking-list { display: grid; gap: .85rem; }
.empty-state { margin: 0; color: var(--muted); }
.booking { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 1rem; border: 1px solid var(--line); border-radius: .55rem; }
.booking h3 { margin: 0 0 .25rem; font-size: 1.05rem; }
.booking p { margin: 0; color: var(--muted); }
.booking[data-status="cancelled"] { opacity: .7; background: #f8fafc; }
.booking[data-status="cancelled"] h3 { text-decoration: line-through; }
.cancel-button { flex: 0 0 auto; padding: .55rem .8rem; color: #7f1d1d; background: #fee2e2; }
.cancel-button:hover { background: #fecaca; }
@media (max-width: 600px) { .page-shell { padding: 2rem 0; } .form-grid { grid-template-columns: 1fr; } .field-wide { grid-column: auto; } .booking { align-items: flex-start; flex-direction: column; } }

application.javascript:
const form = document.querySelector('#booking-form');
const nameInput = document.querySelector('[data-testid="booking-name"]');
const emailInput = document.querySelector('[data-testid="booking-email"]');
const dateInput = document.querySelector('[data-testid="booking-date"]');
const timeInput = document.querySelector('[data-testid="booking-time"]');
const typeInput = document.querySelector('[data-testid="booking-type"]');
const list = document.querySelector('[data-testid="booking-list"]');
const confirmation = document.querySelector('[data-testid="booking-confirmation"]');
const errorMessage = document.querySelector('#form-error');
const emptyState = document.querySelector('#empty-state');
const count = document.querySelector('#booking-count');
let bookings = [];

function getToday() {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${now.getFullYear()}-${month}-${day}`;
}

function showError(message) {
  errorMessage.textContent = message;
  errorMessage.hidden = false;
}

function clearMessages() {
  errorMessage.textContent = '';
  errorMessage.hidden = true;
  confirmation.textContent = '';
  confirmation.hidden = true;
}

function formatDate(value) {
  return new Intl.DateTimeFormat(undefined, { dateStyle: 'long' }).format(new Date(`${value}T00:00:00`));
}

function renderBookings() {
  list.querySelectorAll('[data-testid="booking"]').forEach((item) => item.remove());
  emptyState.hidden = bookings.length > 0;
  count.textContent = `${bookings.length} booking${bookings.length === 1 ? '' : 's'}`;
  bookings.forEach((booking) => list.appendChild(createBookingElement(booking)));
}

function createBookingElement(booking) {
  const article = document.createElement('article');
  article.className = 'booking';
  article.dataset.testid = 'booking';
  article.dataset.status = booking.cancelled ? 'cancelled' : 'active';

  const details = document.createElement('div');
  const heading = document.createElement('h3');
  heading.dataset.testid = 'booking-name-display';
  heading.textContent = booking.name;
  const description = document.createElement('p');
  description.textContent = `${booking.type} · ${formatDate(booking.date)} at ${booking.time} · ${booking.email}`;
  details.append(heading, description);

  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'cancel-button';
  button.dataset.testid = 'booking-cancel';
  button.textContent = booking.cancelled ? 'Cancelled' : 'Cancel booking';
  button.disabled = booking.cancelled;
  button.addEventListener('click', () => cancelBooking(booking.id));
  article.append(details, button);
  return article;
}

function cancelBooking(id) {
  const booking = bookings.find((item) => item.id === id);
  if (booking) {
    booking.cancelled = true;
    renderBookings();
  }
}

function handleSubmit(event) {
  event.preventDefault();
  clearMessages();
  if (!form.reportValidity()) return;
  if (dateInput.value < getToday()) {
    showError('Please choose today or a future date.');
    dateInput.focus();
    return;
  }
  const booking = {
    id: `${Date.now()}-${bookings.length}`,
    name: nameInput.value.trim(),
    email: emailInput.value.trim(),
    date: dateInput.value,
    time: timeInput.value,
    type: typeInput.value,
    cancelled: false
  };
  if (!booking.name || !booking.email) {
    showError('Please complete all required fields.');
    return;
  }
  bookings.push(booking);
  renderBookings();
  confirmation.textContent = `Booking confirmed for ${booking.name}.`;
  confirmation.hidden = false;
  form.reset();
  dateInput.min = getToday();
}

dateInput.min = getToday();
form.addEventListener('submit', handleSubmit);
